import{db}from"@/lib/db";import{ArtworkGrid}from"@/components/artwork-grid";import{getLocale,getMessages,localizeArtworks}from"@/lib/i18n-server";import{artworkSearchWhere}from"@/lib/artwork-search";export const dynamic="force-dynamic";export default async function Search({searchParams}:PageProps<"/search">){const{q=""}=await searchParams;const query=String(q).trim().slice(0,100);const[raw,locale,m]=await Promise.all([db.artwork.findMany({where:{status:"PUBLISHED",deletedAt:null,...artworkSearchWhere(query)},include:{asset:true,author:true,category:true},orderBy:{publishedAt:"desc"},take:50}),getLocale(),getMessages()]);const works=await localizeArtworks(raw,locale);return <section className="section"><span className="eyebrow">{m.find}</span><h1>{m.search}</h1><form className="search"><input name="q" defaultValue={query} placeholder={m.searchPlaceholder}/><button>{m.searchButton}</button></form><p>{query&&`${m.found}: ${works.length}`}</p><ArtworkGrid items={works} locale={locale} m={m}/></section>}